// ТоварыСвернуто свернута по Номенклатуре в ОбработкаПроведения
Процедура СформироватьДвиженияСебестоимости(ТоварыСвернуто, Отказ)

	Блокировка = Новый БлокировкаДанных;
	ЭлементБлокировки = Блокировка.Добавить("РегистрНакопления.СебестоимостьТоваров");
	ЭлементБлокировки.УстановитьЗначение("Организация", Организация);
	ЭлементБлокировки.УстановитьЗначение("Склад", Склад);
	ЭлементБлокировки.Режим = РежимБлокировкиДанных.Исключительный;
	Блокировка.Заблокировать();

	Запрос = Новый Запрос;
	Запрос.Текст =
	"ВЫБРАТЬ
	|	Остатки.Номенклатура КАК Номенклатура,
	|	Остатки.КоличествоОстаток КАК Количество,
	|	Остатки.СуммаОстаток КАК Сумма
	|ИЗ
	|	РегистрНакопления.СебестоимостьТоваров.Остатки(
	|			&Граница,
	|			Организация = &Организация
	|				И Склад = &Склад
	|				И Номенклатура В (&СписокНоменклатуры)) КАК Остатки";

	Запрос.УстановитьПараметр("Граница", Новый Граница(МоментВремени(), ВидГраницы.Исключая));
	Запрос.УстановитьПараметр("Организация", Организация);
	Запрос.УстановитьПараметр("Склад", Склад);
	Запрос.УстановитьПараметр("СписокНоменклатуры", ТоварыСвернуто.ВыгрузитьКолонку("Номенклатура"));
	Остатки = Запрос.Выполнить().Выгрузить();

	Движения.СебестоимостьТоваров.Записывать = Истина;
	Для Каждого СтрокаТовара Из ТоварыСвернуто Цикл
		НайденныйОстаток = Остатки.Найти(СтрокаТовара.Номенклатура, "Номенклатура");
		Если НайденныйОстаток = Неопределено Или НайденныйОстаток.Количество <= 0 Тогда
			Продолжить;
		КонецЕсли;
		Движение = Движения.СебестоимостьТоваров.ДобавитьРасход();
		Движение.Период = Дата;
		Движение.Организация = Организация;
		Движение.Склад = Склад;
		Движение.Номенклатура = СтрокаТовара.Номенклатура;
		Движение.Количество = СтрокаТовара.Количество;
		Движение.Сумма = Окр(НайденныйОстаток.Сумма / НайденныйОстаток.Количество * СтрокаТовара.Количество, 2);
	КонецЦикла;

КонецПроцедуры

// Общий модуль РаботаСОбъектамиВызовСервера (Сервер, Вызов сервера)

Функция ДанныеОбъектаДляФормы(Ссылка, ИменаРеквизитов) Экспорт

	УстановитьПривилегированныйРежим(Истина);

	ИмяТаблицы = Ссылка.Метаданные().ПолноеИмя();

	Запрос = Новый Запрос;
	Запрос.Текст = СтрШаблон(
		"ВЫБРАТЬ
		|	%1
		|ИЗ
		|	%2 КАК Т
		|ГДЕ
		|	Т.Ссылка = &Ссылка", ИменаРеквизитов, ИмяТаблицы);
	Запрос.УстановитьПараметр("Ссылка", Ссылка);

	РезультатЗапроса = Запрос.Выполнить();
	Выборка = РезультатЗапроса.Выбрать();

	Результат = Новый Структура;
	Если Выборка.Следующий() Тогда
		Для Каждого Колонка Из РезультатЗапроса.Колонки Цикл
			Результат.Вставить(Колонка.Имя, Выборка[Колонка.Имя]);
		КонецЦикла;
	КонецЕсли;

	Возврат Результат;

КонецФункции

Процедура ЗакрытьУстаревшиеЗаявкиРегламент() Экспорт

	ОбщегоНазначения.ПриНачалеВыполненияРегламентногоЗадания(Метаданные.РегламентныеЗадания.ЗакрытиеУстаревшихЗаявок);

	Запрос = Новый Запрос;
	Запрос.Текст =
	"ВЫБРАТЬ ПЕРВЫЕ 500
	|	Заявка.Ссылка КАК Ссылка
	|ИЗ
	|	Справочник.ЗаявкиНаЗакупку КАК Заявка
	|ГДЕ
	|	Заявка.Статус = ЗНАЧЕНИЕ(Перечисление.СтатусыЗаявок.Открыта)
	|	И Заявка.ДатаСоздания < &ГраницаАктуальности
	|	И НЕ Заявка.Ссылка В (&Пропущенные)";
	Запрос.УстановитьПараметр("ГраницаАктуальности", ТекущаяДатаСеанса() - 90 * 86400);
	Пропущенные = Новый Массив;

	Пока Истина Цикл
		Запрос.УстановитьПараметр("Пропущенные", Пропущенные);
		Выборка = Запрос.Выполнить().Выбрать();
		Если Выборка.Количество() = 0 Тогда
			Прервать;
		КонецЕсли;
		Пока Выборка.Следующий() Цикл
			// Каждая заявка отдельно: занятую пользователем пропускаем до следующего запуска
			Попытка
				ЗаявкаОбъект = Выборка.Ссылка.ПолучитьОбъект();
				ЗаявкаОбъект.Заблокировать();
				ЗаявкаОбъект.Статус = Перечисления.СтатусыЗаявок.Закрыта;
				ЗаявкаОбъект.Записать();
			Исключение
				Пропущенные.Добавить(Выборка.Ссылка);
				ЗаписьЖурналаРегистрации(НСтр("ru = 'Закрытие устаревших заявок'"), УровеньЖурналаРегистрации.Предупреждение,
					Метаданные.Справочники.ЗаявкиНаЗакупку, Выборка.Ссылка,
					ОбработкаОшибок.ПодробноеПредставлениеОшибки(ИнформацияОбОшибке()));
			КонецПопытки;
		КонецЦикла;
	КонецЦикла;

КонецПроцедуры

Процедура ОбработкаПроведения(Отказ, РежимПроведения)

	Если РежимПроведения = РежимПроведенияДокумента.Оперативный Тогда
		Запрос = Новый Запрос;
		Запрос.Текст =
		"ВЫБРАТЬ
		|	Остатки.Номенклатура КАК Номенклатура,
		|	Остатки.КоличествоОстаток КАК Остаток
		|ИЗ
		|	РегистрНакопления.ТоварыНаСкладах.Остатки(,
		|			Склад = &Склад
		|				И Номенклатура В (&Номенклатура)) КАК Остатки";
		Запрос.УстановитьПараметр("Склад", Склад);
		Запрос.УстановитьПараметр("Номенклатура", Товары.ВыгрузитьКолонку("Номенклатура"));
		Остатки = Запрос.Выполнить().Выгрузить();

		Для Каждого СтрокаТовара Из Товары Цикл
			НайденнаяСтрока = Остатки.Найти(СтрокаТовара.Номенклатура, "Номенклатура");
			Остаток = ?(НайденнаяСтрока = Неопределено, 0, НайденнаяСтрока.Остаток);
			Если Остаток < СтрокаТовара.Количество Тогда
				ОбщегоНазначения.СообщитьПользователю(СтрШаблон(НСтр("ru = 'Недостаточно %1: остаток %2'"),
					СтрокаТовара.Номенклатура, Остаток), ЭтотОбъект, , , Отказ);
			КонецЕсли;
		КонецЦикла;

		Если Отказ Тогда
			Возврат;
		КонецЕсли;
	КонецЕсли;

	Движения.ТоварыНаСкладах.Записывать = Истина;
	Для Каждого СтрокаТовара Из Товары Цикл
		Движение = Движения.ТоварыНаСкладах.ДобавитьРасход();
		Движение.Период = Дата;
		Движение.Склад = Склад;
		Движение.Номенклатура = СтрокаТовара.Номенклатура;
		Движение.Количество = СтрокаТовара.Количество;
	КонецЦикла;

КонецПроцедуры

&ИзменениеИКонтроль("ОбработкаЗаполнения")
Процедура Расш1_ОбработкаЗаполнения(ДанныеЗаполнения, ТекстЗаполнения, СтандартнаяОбработка)

	Если ТипЗнч(ДанныеЗаполнения) = Тип("ДокументСсылка.ЗаказКлиента") Тогда
		ЗаполнитьЗначенияСвойств(ЭтотОбъект, ДанныеЗаполнения, "Организация, Контрагент, Договор, Склад");
		#Вставка
		Расш1_ДатаОтгрузкиПлан = ДанныеЗаполнения.ЖелаемаяДатаОтгрузки;
		Комментарий = СтрШаблон(НСтр("ru = 'Основание: %1'"), ДанныеЗаполнения);
		#КонецВставки
		Для Каждого СтрокаЗаказа Из ДанныеЗаполнения.Товары Цикл
			НоваяСтрока = Товары.Добавить();
			ЗаполнитьЗначенияСвойств(НоваяСтрока, СтрокаЗаказа);
			#Удаление
			НоваяСтрока.Скидка = 0;
			#КонецУдаления
		КонецЦикла;
		ЗаказКлиента = ДанныеЗаполнения;
	ИначеЕсли ТипЗнч(ДанныеЗаполнения) = Тип("Структура") Тогда
		ЗаполнитьЗначенияСвойств(ЭтотОбъект, ДанныеЗаполнения);
	КонецЕсли;

	Ответственный = Пользователи.ТекущийПользователь();

КонецПроцедуры

Процедура ЗагрузитьПакетКонтрагентов(ДанныеПакета) Экспорт

	НачатьТранзакцию();
	Попытка
		Для Каждого ДанныеКонтрагента Из ДанныеПакета Цикл
			Попытка
				Ссылка = Справочники.Контрагенты.НайтиПоРеквизиту("ИНН", ДанныеКонтрагента.ИНН);
				Если Ссылка.Пустая() Тогда
					Объект = Справочники.Контрагенты.СоздатьЭлемент();
				Иначе
					Объект = Ссылка.ПолучитьОбъект();
				КонецЕсли;
				ЗаполнитьЗначенияСвойств(Объект, ДанныеКонтрагента, "Наименование, ИНН, КПП, ЮридическийАдрес");
				Объект.ОбменДанными.Загрузка = Истина;
				Объект.Записать();
			Исключение
				ЗаписьЖурналаРегистрации("ОбменССайтом.ЗагрузкаКонтрагентов", УровеньЖурналаРегистрации.Ошибка, , ,
					СтрШаблон("ИНН %1: %2", ДанныеКонтрагента.ИНН, ПодробноеПредставлениеОшибки(ИнформацияОбОшибке())));
			КонецПопытки;
		КонецЦикла;
		ЗафиксироватьТранзакцию();
	Исключение
		ОтменитьТранзакцию();
		ВызватьИсключение;
	КонецПопытки;

КонецПроцедуры

