Функция ПечатьТоварнойНакладной(МассивОбъектов, ОбъектыПечати) Экспорт

	ТабличныйДокумент = Новый ТабличныйДокумент;
	ТабличныйДокумент.КлючПараметровПечати = "ПАРАМЕТРЫ_ПЕЧАТИ_ТоварнаяНакладная";
	Макет = УправлениеПечатью.МакетПечатнойФормы("Документ.РеализацияТоваров.ПФ_MXL_ТоварнаяНакладная");
	ОбластьШапки = Макет.ПолучитьОбласть("Шапка");
	ОбластьСтроки = Макет.ПолучитьОбласть("Строка");

	Для Каждого ДокументСсылка Из МассивОбъектов Цикл
		Если ТабличныйДокумент.ВысотаТаблицы > 0 Тогда
			ТабличныйДокумент.ВывестиГоризонтальныйРазделительСтраниц();
		КонецЕсли;
		НомерСтрокиНачало = ТабличныйДокумент.ВысотаТаблицы + 1;

		ОбластьШапки.Параметры.Заполнить(ДокументСсылка);
		ОбластьШапки.Параметры.ПредставлениеПокупателя = ДокументСсылка.Контрагент.НаименованиеПолное;
		ТабличныйДокумент.Вывести(ОбластьШапки);

		Для Каждого СтрокаТовара Из ДокументСсылка.Товары Цикл
			ОбластьСтроки.Параметры.Заполнить(СтрокаТовара);
			ОбластьСтроки.Параметры.Артикул = СтрокаТовара.Номенклатура.Артикул;
			ОбластьСтроки.Параметры.ЕдиницаИзмерения = СтрокаТовара.Номенклатура.ЕдиницаИзмерения.Наименование;

			Запрос = Новый Запрос("ВЫБРАТЬ ПЕРВЫЕ 1 Ш.Штрихкод КАК Штрихкод
				|ИЗ РегистрСведений.ШтрихкодыНоменклатуры КАК Ш
				|ГДЕ Ш.Номенклатура = &Номенклатура");
			Запрос.УстановитьПараметр("Номенклатура", СтрокаТовара.Номенклатура);
			Выборка = Запрос.Выполнить().Выбрать();
			ОбластьСтроки.Параметры.Штрихкод = ?(Выборка.Следующий(), Выборка.Штрихкод, "");

			ТабличныйДокумент.Вывести(ОбластьСтроки);
		КонецЦикла;

		УправлениеПечатью.ЗадатьОбластьПечатиДокумента(ТабличныйДокумент, НомерСтрокиНачало, ОбъектыПечати, ДокументСсылка);
	КонецЦикла;

	Возврат ТабличныйДокумент;

КонецФункции

&Вместо("ПередЗаписью")
Процедура Расш1_ПередЗаписью(Отказ, РежимЗаписи, РежимПроведения)

	Если ОбменДанными.Загрузка Тогда
		Возврат;
	КонецЕсли;

	Если Не ЗначениеЗаполнено(Расш1_КаналПродаж) Тогда
		Расш1_КаналПродаж = Справочники.Расш1_КаналыПродаж.КаналПоУмолчанию(Контрагент);
	КонецЕсли;

	Если РежимЗаписи = РежимЗаписиДокумента.Проведение
		И Расш1_КаналПродаж = Справочники.Расш1_КаналыПродаж.Маркетплейс
		И Не ЗначениеЗаполнено(Расш1_НомерЗаказаМаркетплейса) Тогда
		ОбщегоНазначения.СообщитьПользователю(НСтр("ru = 'Не указан номер заказа маркетплейса'"),
			ЭтотОбъект, "Расш1_НомерЗаказаМаркетплейса", , Отказ);
	КонецЕсли;

КонецПроцедуры

Функция СледующийНомерПартии(Номенклатура, Склад) Экспорт

	Блокировка = Новый БлокировкаДанных;
	ЭлементБлокировки = Блокировка.Добавить("РегистрСведений.СчетчикиПартий");
	ЭлементБлокировки.УстановитьЗначение("Номенклатура", Номенклатура);
	ЭлементБлокировки.УстановитьЗначение("Склад", Склад);

	НачатьТранзакцию();
	Попытка
		Блокировка.Заблокировать();

		МенеджерЗаписи = РегистрыСведений.СчетчикиПартий.СоздатьМенеджерЗаписи();
		МенеджерЗаписи.Номенклатура = Номенклатура;
		МенеджерЗаписи.Склад = Склад;
		МенеджерЗаписи.Прочитать();
		Если Не МенеджерЗаписи.Выбран() Тогда
			МенеджерЗаписи.Номенклатура = Номенклатура;
			МенеджерЗаписи.Склад = Склад;
		КонецЕсли;
		МенеджерЗаписи.ПоследнийНомер = МенеджерЗаписи.ПоследнийНомер + 1;
		МенеджерЗаписи.Записать();
		НомерПартии = МенеджерЗаписи.ПоследнийНомер;

		ЗафиксироватьТранзакцию();
	Исключение
		ОтменитьТранзакцию();
		ВызватьИсключение;
	КонецПопытки;

	Возврат НомерПартии;

КонецФункции

// Общий модуль ИнтеграцияСПоставщикомСервер (Сервер, без вызова сервера)

Функция ОтправитьЗаказПоставщику(ЗаказСсылка) Экспорт

	Настройки = Константы.НастройкиAPIПоставщика.Получить().Получить();

	УстановитьПривилегированныйРежим(Истина);
	Токен = ОбщегоНазначения.ПрочитатьДанныеИзБезопасногоХранилища(Настройки.ВладелецНастроек, "ТокенДоступа");
	УстановитьПривилегированныйРежим(Ложь);

	Если Не ЗначениеЗаполнено(Токен) Тогда
		ВызватьИсключение НСтр("ru = 'Не задан токен доступа к API поставщика'");
	КонецЕсли;

	Соединение = Новый HTTPСоединение(Настройки.Сервер, 443, , , , 30,
		Новый ЗащищенноеСоединениеOpenSSL(, Новый СертификатыУдостоверяющихЦентровОС));

	Запрос = Новый HTTPЗапрос("/api/v2/orders");
	Запрос.Заголовки.Вставить("Authorization", "Bearer " + Токен);
	Запрос.Заголовки.Вставить("Content-Type", "application/json; charset=utf-8");
	Запрос.УстановитьТелоИзСтроки(ТелоЗаказаJSON(ЗаказСсылка), КодировкаТекста.UTF8,
		ИспользованиеByteOrderMark.НеИспользовать);

	Ответ = Соединение.ОтправитьДляОбработки(Запрос);
	Если Ответ.КодСостояния <> 200 И Ответ.КодСостояния <> 201 Тогда
		ВызватьИсключение СтрШаблон(НСтр("ru = 'Поставщик вернул код %1: %2'"),
			Ответ.КодСостояния, Лев(Ответ.ПолучитьТелоКакСтроку(), 1000));
	КонецЕсли;

	Возврат Ответ.ПолучитьТелоКакСтроку(КодировкаТекста.UTF8);

КонецФункции

// Отложенный обработчик обновления, версия 2.4.7.15
Процедура ЗаполнитьВидОперацииВозвратов(Параметры) Экспорт

	Запрос = Новый Запрос;
	Запрос.Текст =
	"ВЫБРАТЬ
	|	Возврат.Ссылка КАК Ссылка
	|ИЗ
	|	Документ.ВозвратТоваровОтКлиента КАК Возврат
	|ГДЕ
	|	Возврат.ВидОперации = ЗНАЧЕНИЕ(Перечисление.ВидыОперацийВозврата.ПустаяСсылка)";
	Выборка = Запрос.Выполнить().Выбрать();

	Пока Выборка.Следующий() Цикл
		ДокументОбъект = Выборка.Ссылка.ПолучитьОбъект();
		ДокументОбъект.ВидОперации = ?(ЗначениеЗаполнено(ДокументОбъект.ЗаказКлиента),
			Перечисления.ВидыОперацийВозврата.ПоЗаказу,
			Перечисления.ВидыОперацийВозврата.БезЗаказа);
		Если ДокументОбъект.Проведен Тогда
			ДокументОбъект.Записать(РежимЗаписиДокумента.Проведение);
		Иначе
			ДокументОбъект.Записать();
		КонецЕсли;
	КонецЦикла;

	Параметры.ОбработкаЗавершена = Истина;

КонецПроцедуры

// Подписка ЖурналИзмененияЦенПередЗаписью
// Источник: РегистрСведенийНаборЗаписей.ЦеныНоменклатуры, событие ПередЗаписью
Процедура ЖурналИзмененияЦенПередЗаписью(Источник, Отказ, Замещение) Экспорт

	Если Источник.ОбменДанными.Загрузка Тогда
		Возврат;
	КонецЕсли;

	// У пользователей нет прав на журнал, он ведётся служебно
	УстановитьПривилегированныйРежим(Истина);

	ИдентификаторИзменения = Новый УникальныйИдентификатор;
	Набор = РегистрыСведений.ЖурналИзмененияЦен.СоздатьНаборЗаписей();
	Набор.Отбор.ИдентификаторИзменения.Установить(ИдентификаторИзменения);

	Для Каждого Запись Из Источник Цикл
		НоваяЗапись = Набор.Добавить();
		ЗаполнитьЗначенияСвойств(НоваяЗапись, Запись, "Номенклатура, ВидЦены, Цена");
		НоваяЗапись.ИдентификаторИзменения = ИдентификаторИзменения;
		НоваяЗапись.ДатаЦены = Запись.Период;
		НоваяЗапись.ДатаИзменения = ТекущаяДатаСеанса();
		НоваяЗапись.Пользователь = Пользователи.ТекущийПользователь();
	КонецЦикла;

	Набор.Записать();

КонецПроцедуры
